const EPSILON = 0.005;
const rowsOf = (value) => {
  let v = value;
  for (let i = 0; i < 4 && v && !Array.isArray(v); i++) v = v.items ?? v.output ?? v.data ?? (v.json && v.json !== v ? v.json : undefined);
  return Array.isArray(v) ? v : [];
};
const nodeRows = (name) => { try { return rowsOf($node[name].json); } catch (e) { return []; } };
const gql = (value) => JSON.stringify(value).replace(/"([A-Za-z_][A-Za-z0-9_]*)":/g, "$1:");

function computeQuantities(input   





 )                {
  const wanted = input.productIds ? new Set(input.productIds) : null
  const rows = new Map                     ()
  const row = (productId        , locationId        ) => {
    const key = `${productId}|${locationId}`
    let entry = rows.get(key)
    if (!entry) {
      entry = { productId, locationId, onHand: 0, picked: 0, reserved: 0, available: 0, onOrder: 0, inTransit: 0, anticipated: 0 }
      rows.set(key, entry)
    }
    return entry
  }
  const keep = (productId        ) => !wanted || wanted.has(productId)
  const num = (value         ) => Number(value ?? 0) || 0

  for (const balance of input.balances) {
    if (keep(balance.productId)) row(balance.productId, balance.locationId).onHand += num(balance.onHand)
  }
  for (const order of input.salesOrders) {
    for (const line of order.lines ?? []) {
      if (!keep(line.productId) || num(line.stdQty) <= 0) continue
      const entry = row(line.productId, order.locationId)
      entry.reserved += Math.max(0, num(line.stdQty) - num(line.pickedQty))
      entry.picked += Math.max(0, num(line.pickedQty) - num(line.shippedQty))
    }
  }
  for (const order of input.purchaseOrders) {
    for (const line of order.lines ?? []) {
      if (!keep(line.productId) || num(line.stdQty) <= 0) continue
      row(line.productId, order.receiveLocationId).onOrder += Math.max(0, num(line.stdQty) - num(line.receivedQty))
    }
  }
  for (const transfer of input.transfers) {
    for (const line of transfer.lines ?? []) {
      if (!keep(line.productId)) continue
      if (transfer.status === "open") {
        row(line.productId, transfer.fromLocationId).reserved += num(line.qty)
        row(line.productId, transfer.toLocationId).onOrder += num(line.qty)
      } else if (transfer.status === "in_transit") {
        const entry = row(line.productId, transfer.toLocationId)
        entry.inTransit += num(line.qty)
        entry.onOrder += num(line.qty)
      }
    }
  }
  const result                = []
  for (const entry of rows.values()) {
    entry.available = entry.onHand - entry.reserved
    entry.anticipated = entry.onHand - entry.reserved + entry.onOrder
    result.push(entry)
  }
  return result
}
function computeReorder(
  settings                     ,
  quantities                                                                                                                     
)                 {
  const byKey = new Map(quantities.map((row) => [`${row.productId}|${row.locationId}`, row]))
  const outcome                 = { suggestions: [], alerts: [] }
  for (const setting of settings) {
    const point = Number(setting.reorderPoint ?? 0)
    const q = byKey.get(`${setting.productId}|${setting.locationId}`) ?? { onHand: 0, reserved: 0, onOrder: 0, anticipated: 0 }
    const below = q.anticipated < point
    if (below) {
      // Order the reorder quantity, or at least enough to get back to the point.
      const suggestedQty = Math.max(Number(setting.reorderQty ?? 0), point - q.anticipated)
      outcome.suggestions.push({
        productId: setting.productId,
        locationId: setting.locationId,
        onHand: q.onHand,
        reserved: q.reserved,
        onOrder: q.onOrder,
        anticipated: q.anticipated,
        reorderPoint: point,
        suggestedQty,
        method: setting.method || "purchase",
        vendorId: setting.vendorId ?? null,
        sourceLocationId: setting.sourceLocationId ?? null,
      })
    }
    if (below && !setting.isAlerting) outcome.alerts.push({ settingId: setting.ItemId, productId: setting.productId, locationId: setting.locationId, alerting: true })
    if (!below && setting.isAlerting) outcome.alerts.push({ settingId: setting.ItemId, productId: setting.productId, locationId: setting.locationId, alerting: false })
  }
  return outcome
}
const settings = nodeRows("Get Settings");
const quantities = computeQuantities({
  balances: nodeRows("Get Balances"),
  transfers: nodeRows("Get Transfers"),
  salesOrders: nodeRows("Get Open Sales"),
  purchaseOrders: nodeRows("Get Open Purchases"),
});
const outcome = computeReorder(settings, quantities);
const existing = nodeRows("Get Suggestions");
const computedAt = new Date().toISOString();
const key = (r) => r.productId + "|" + r.locationId;
const wanted = new Map(outcome.suggestions.map((r) => [key(r), r]));
const parts = [];
let n = 0;
for (const row of existing) if (!wanted.has(key(row))) parts.push(`d${n++}: deleteReorderSuggestion(filter: ${JSON.stringify(JSON.stringify({ ItemId: row.ItemId }))}) { acknowledged }`);
for (const row of outcome.suggestions) {
  const current = existing.find((e) => key(e) === key(row));
  if (current) parts.push(`s${n++}: updateReorderSuggestion(filter: ${JSON.stringify(JSON.stringify({ ItemId: current.ItemId }))}, input: ${gql({ ...row, computedAt })}) { acknowledged }`);
  else parts.push(`s${n++}: insertReorderSuggestion(input: ${gql({ ...row, computedAt })}) { acknowledged }`);
}
for (const alert of outcome.alerts) {
  const filter = JSON.stringify({ ItemId: alert.settingId, isAlerting: alert.alerting ? { $ne: true } : true });
  const input = alert.alerting ? { isAlerting: true, lastAlertedAt: computedAt } : { isAlerting: false };
  parts.push(`a${n++}: updateReorderSetting(filter: ${JSON.stringify(filter)}, input: ${gql(input)}) { acknowledged }`);
}
const details = `${outcome.suggestions.length} below reorder point, ${outcome.alerts.filter((a) => a.alerting).length} new alerts`;
parts.push(`log: insertWorkflowRun(input: ${gql({ workflow: "reorder-check", status: "ok", details, ranAt: computedAt })}) { acknowledged }`);
return { query: `mutation { ${parts.join(" ")} }`, details };
